function shortWorkflow(name) {
  return tidy(String(name || '')
    .replace(/\s*\[(UAT|CANDIDATE|TEMP|TEST)\]\s*/gi, ' ')
    .replace(/^\s*FINMENTOR\s+/i, '')
    .replace(/\s+(PREMIUM|FINAL|SECURE|CANDIDATE|GUARDED|AI GUARDED|v\d+)\b/gi, ''), 60);
}

