  const lines = text.split('\n').map(v => safe(v)).filter(Boolean).slice(0, maxLines);
  if (!lines.length) return '—';
  const out = lines.map(v => `• ${v.replace(/^[-•]\s*/, '')}`).join('\n');
  return out.length > maxChars ? out.slice(0, maxChars).trim() + '...' : out;
}

